import { ProxyNodeConfig } from '../types';

/**
 * Generates production-ready Cloudflare Pages `_worker.js` script.
 * Fully supports VLESS WebSocket, early data, and ProxyIP outbound socket relay.
 */
export function generatePagesWorkerScript(config: ProxyNodeConfig): string {
  const defaultUuid = config.uuid.trim();
  const defaultProxyIp = config.proxyIp.trim() || 'proxyip.sg.cmliussss.net';

  return `/**
 * Cloudflare Pages / Workers V2Ray & VLESS Reverse Proxy
 * Enhanced with ProxyIP relay via ${defaultProxyIp}
 * Auto-generated by CF Pages V2Ray & ProxyIP Architect
 */

import { connect } from 'cloudflare:sockets';

const DEFAULT_UUID = '${defaultUuid}';
const DEFAULT_PROXYIP = '${defaultProxyIp}';

export default {
  async fetch(request, env, ctx) {
    try {
      const url = new URL(request.url);
      const uuid = env.UUID || DEFAULT_UUID;
      const proxyIP = env.PROXYIP || DEFAULT_PROXYIP;

      // Handle subscription query endpoints: /sub, /clash, /singbox
      if (url.pathname === '/sub' || url.pathname === '/clash' || url.pathname === '/singbox') {
        return handleSubscription(request, url, uuid, proxyIP);
      }

      // Check for WebSocket upgrade request
      const upgradeHeader = request.headers.get('Upgrade');
      if (!upgradeHeader || upgradeHeader.toLowerCase() !== 'websocket') {
        // Return benign disguising landing page if normal HTTP request
        return handleDisguisePage(request, url);
      }

      // Handle VLESS WebSocket proxying
      return handleVlessOverWebSocket(request, uuid, proxyIP);
    } catch (err) {
      return new Response(\`Server Internal Error: \${err.message}\`, { status: 500 });
    }
  }
};

/**
 * Handles VLESS binary stream parsing & outbound TCP socket via ProxyIP
 */
async function handleVlessOverWebSocket(request, userID, proxyIP) {
  const webSocketPair = new WebSocketPair();
  const [clientWs, serverWs] = Object.values(webSocketPair);
  serverWs.accept();

  let address = '';
  let portWithHeader = 0;
  let remoteSocket = null;
  let isDns = false;

  // Process early data if present
  const earlyDataHeader = request.headers.get('sec-websocket-protocol');
  let earlyData = null;
  if (earlyDataHeader) {
    try {
      earlyData = base64ToArrayBuffer(earlyDataHeader);
    } catch (e) {
      // ignore invalid early data
    }
  }

  // ReadableStream from WebSocket
  const wsStream = makeReadableWebSocketStream(serverWs, earlyData);

  wsStream.pipeTo(new WritableStream({
    async write(chunk) {
      if (remoteSocket) {
        const writer = remoteSocket.writable.getWriter();
        await writer.write(chunk);
        writer.releaseLock();
        return;
      }

      // Parse VLESS binary header:
      // Byte 0: version (0)
      // Byte 1-16: UUID
      // Byte 17: proto-addons length
      // Byte 18 + addonLen: Command (1 = TCP)
      // Byte 19 + addonLen: Port (2 bytes)
      // Byte 21 + addonLen: Address type (1 = IPv4, 2 = Domain, 3 = IPv6)
      if (chunk.byteLength < 24) return;

      const version = new Uint8Array(chunk.slice(0, 1));
      const clientUUIDArray = new Uint8Array(chunk.slice(1, 17));
      const clientUUID = stringifyUUID(clientUUIDArray);

      if (clientUUID.toLowerCase() !== userID.toLowerCase()) {
        serverWs.close(1008, 'UUID authentication failed');
        return;
      }

      const optLength = new Uint8Array(chunk.slice(17, 18))[0];
      const command = new Uint8Array(chunk.slice(18 + optLength, 19 + optLength))[0];

      if (command !== 1) {
        serverWs.close(1003, 'Unsupported command (TCP only)');
        return;
      }

      const portIndex = 19 + optLength;
      const portBuffer = chunk.slice(portIndex, portIndex + 2);
      const port = new DataView(portBuffer).getUint16(0);

      const addressIndex = portIndex + 2;
      const addressBuffer = new Uint8Array(chunk.slice(addressIndex, addressIndex + 1));
      const addressType = addressBuffer[0];
      let addressLength = 0;
      let addressValueIndex = addressIndex + 1;

      if (addressType === 1) {
        // IPv4 (4 bytes)
        addressLength = 4;
        address = new Uint8Array(chunk.slice(addressValueIndex, addressValueIndex + addressLength)).join('.');
      } else if (addressType === 2) {
        // Domain name (first byte is length)
        addressLength = new Uint8Array(chunk.slice(addressValueIndex, addressValueIndex + 1))[0];
        addressValueIndex += 1;
        address = new TextDecoder().decode(chunk.slice(addressValueIndex, addressValueIndex + addressLength));
      } else if (addressType === 3) {
        // IPv6 (16 bytes)
        addressLength = 16;
        const dataView = new DataView(chunk.slice(addressValueIndex, addressValueIndex + addressLength));
        const ipv6 = [];
        for (let i = 0; i < 8; i++) {
          ipv6.push(dataView.getUint16(i * 2).toString(16));
        }
        address = ipv6.join(':');
      }

      const rawClientData = chunk.slice(addressValueIndex + addressLength);

      // Connect to upstream target via ProxyIP relay or direct
      const targetHost = (proxyIP && proxyIP.trim().length > 0) ? proxyIP.trim() : address;
      const targetPort = port;

      try {
        remoteSocket = connect({
          hostname: targetHost,
          port: targetPort
        });

        // Write VLESS response header (version 0, addons 0)
        serverWs.send(new Uint8Array([version[0], 0]));

        // Forward initial payload to remote socket
        if (rawClientData.byteLength > 0) {
          const writer = remoteSocket.writable.getWriter();
          await writer.write(rawClientData);
          writer.releaseLock();
        }

        // Pipe upstream response back to WebSocket
        remoteSocket.readable.pipeTo(new WritableStream({
          write(data) {
            if (serverWs.readyState === WebSocket.OPEN) {
              serverWs.send(data);
            }
          },
          close() {
            serverWs.close();
          },
          abort(err) {
            serverWs.close(1011, err.message);
          }
        })).catch(() => {});

      } catch (err) {
        serverWs.close(1011, \`Proxy connection failed: \${err.message}\`);
      }
    }
  }));

  return new Response(null, {
    status: 101,
    webSocket: clientWs,
  });
}

function makeReadableWebSocketStream(ws, earlyData) {
  return new ReadableStream({
    start(controller) {
      if (earlyData) {
        controller.enqueue(earlyData);
      }
      ws.addEventListener('message', event => {
        controller.enqueue(event.data);
      });
      ws.addEventListener('close', () => {
        controller.close();
      });
      ws.addEventListener('error', err => {
        controller.error(err);
      });
    }
  });
}

function stringifyUUID(bytes) {
  const hex = Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
  return \`\${hex.slice(0, 8)}-\${hex.slice(8, 12)}-\${hex.slice(12, 16)}-\${hex.slice(16, 20)}-\${hex.slice(20)}\`;
}

function base64ToArrayBuffer(base64) {
  base64 = base64.replace(/-/g, '+').replace(/_/g, '/');
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes.buffer;
}

function handleSubscription(request, url, uuid, proxyIP) {
  const host = request.headers.get('Host') || url.host;
  const vlessNode = \`vless://\${uuid}@\${host}:443?encryption=none&security=tls&sni=\${host}&fp=chrome&type=ws&host=\${host}&path=%2F%3Fed%3D2048#CF-Pages-\${proxyIP.replace(/\\./g, '-')}\`;
  const base64Sub = btoa(vlessNode);

  return new Response(base64Sub, {
    headers: {
      'Content-Type': 'text/plain; charset=utf-8',
      'Profile-Update-Interval': '24',
      'Subscription-Userinfo': 'upload=0; download=0; total=1073741824000; expire=0'
    }
  });
}

function handleDisguisePage(request, url) {
  const html = \`<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Edge Gateway Active</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #0f172a; color: #94a3b8; display: flex; align-items: center; justify-content: center; min-height: 100vh; margin: 0; }
    .card { background: #1e293b; padding: 2.5rem; border-radius: 12px; border: 1px solid #334155; max-width: 480px; text-align: center; }
    h1 { color: #f8fafc; font-size: 1.5rem; margin-bottom: 0.5rem; }
    p { font-size: 0.95rem; line-height: 1.5; }
    .code { font-family: monospace; background: #0b0f17; color: #38bdf8; padding: 0.25rem 0.5rem; border-radius: 4px; }
  </style>
</head>
<body>
  <div class="card">
    <h1>Cloudflare Edge Tunnel Active</h1>
    <p>This edge function is actively proxying verified backend connections via <span class="code">\${DEFAULT_PROXYIP}</span>.</p>
    <p style="font-size: 0.8rem; color: #64748b;">Protocol: VLESS WebSocket over TLS · Status: Ready</p>
  </div>
</body>
</html>\`;

  return new Response(html, {
    headers: { 'Content-Type': 'text/html; charset=utf-8' }
  });
}
`;
}
